import { AsyncLocalStorage } from 'node:async_hooks';

/**
 * The trace context follows a request through every await in this process.
 * traceId == the X-Request-ID generated by Nginx, so one ID correlates
 * Nginx logs, service logs, spans and RabbitMQ messages.
 */
export interface TraceContext {
  traceId: string;
  spanId?: string;
  suppressed?: boolean;
}

export const als = new AsyncLocalStorage<TraceContext>();
export const currentContext = (): TraceContext | undefined => als.getStore();

/** Run background work (pollers) without producing traces unless they find something to do. */
export function suppressTracing<T>(fn: () => Promise<T>): Promise<T> {
  return als.run({ traceId: '', suppressed: true }, fn);
}
